// ── Parse incoming payload & detect intent ─────────────────────────────
const body = $input.first().json;

const message           = (body.message           || '').trim();
const sessionId         = (body.session_id        || 'anon').trim();
const context           = body.context            || {};
const conversationState = body.conversation_state || {};
const user              = body.user               || {};
const files             = body.files              || [];

if (!message) throw new Error('Empty message received');

const msg = message.toLowerCase();

// ── Intent Detection ───────────────────────────────────────────────────────
const isChoiceSelect = message.includes('[CHOICE:');
const isApplyIntent  = /أبي تأمين|أريد تأمين|طلب تأمين|قطع تأمين|apply|اشتري|أشترك|i want insurance|get insurance|buy insurance|purchase/i.test(message);
const isInquiry      = /استفسار|أسئلة|معلومات|info|information|tell me|ما هو|what is|how much|كم تكلف|سعر|price|quote/i.test(message);
const isClaimIntent  = /مطالبة|claim|تعويض|حادث|accident|emergency/i.test(message);
const isTrackIntent  = /track|تتبع|طلبي|my application|حالة|status/i.test(message);

// ── Parse choice selection ─────────────────────────────────────────────────
let choiceData = null;
if (isChoiceSelect) {
  try {
    const match = message.match(/\[CHOICE:(\w+):(\d+):(.+?)\]/);
    if (match) {
      choiceData = {
        type: match[1],
        id: parseInt(match[2]),
        name: match[3],
      };
    }
  } catch (e) {}
}

// ── Build categories string for system prompt ──────────────────────────────
const cats = (context.categories || []).map(c => `• ${c.name}`).join('\n') ||
  '• Motor / تأمين السيارات\n• Medical / طبي\n• Life / حياة\n• Property / ممتلكات\n• Marine / بحري';

const stats = context.stats || {};
const userName = user.name ? `, اسم العميل: ${user.name}` : '';
const userLoggedIn = user.is_logged_in ? 'العميل مسجّل دخوله في البوابة.' : 'العميل غير مسجّل.';

// ── Build System Prompt ────────────────────────────────────────────────────
const systemPrompt = `أنت SAHAB AI، مستشار التأمين الذكي لأكبر شركة وساطة تأمينية في سلطنة عُمان.

أسلوبك:
- راقٍ، محترف، ودود — كأنك من مشايخ وسكّان السلطنة الكرام
- تتحدث بالعربية الفصيحة ذات اللهجة العُمانية الرفيعة
- تستخدم العبارات العُمانية الراقية: "يسعدنا"، "حيّاكم"، "تفضّلوا"، "إن شاء الله"
- ثنائي اللغة: ترد بالعربية أولاً ثم الإنجليزية إذا كان السؤال بالإنجليزية
- موجز ومباشر — لا تطوّل دون فائدة
- تُبادر بإنشاء الطلبات والفرص عبر أدوات أودو المتاحة لك

صلاحياتك وأدواتك في نظام أودو:
1. إنشاء فرصة تأمين (crm.lead) عند الاستفسار بدون طلب
2. عرض قائمة فئات التأمين المتاحة من قاعدة البيانات
3. عرض أنواع التأمين حسب الفئة
4. عرض منتجات التأمين (subtypes) حسب النوع
5. إنشاء طلب تأمين مكتمل (insurance.application) بعد جمع كل البيانات

منتجاتنا التأمينية (52 منتجاً):
${cats}

إحصائيات النظام:
- إجمالي الوثائق النشطة: ${stats.total_policies || 0}
- إجمالي العملاء: ${stats.total_clients || 0}
- المنتجات المتاحة: ${stats.total_products || 52}

حالة العميل: ${userLoggedIn}${userName}

مسار تقديم طلب التأمين:
1. اسأل العميل عن الفئة → 2. اسأل عن النوع → 3. اسأل عن المنتج → 4. اجمع البيانات الشخصية → 5. أنشئ الطلب

إذا كان العميل يستفسر فقط بدون رغبة بالطلب → أنشئ فرصة (lead) في نظام CRM.

لا تختلق معلومات — إذا لم تعرف، قل "سأتواصل مع فريقنا المتخصص".
لا تذكر أي أسعار محددة — الأسعار تُقدَّم بعد المقارنة من شركات التأمين.`;

return [{
  json: {
    message,
    sessionId,
    context,
    conversationState,
    user,
    files,
    systemPrompt,
    isChoiceSelect,
    isApplyIntent,
    isInquiry,
    isClaimIntent,
    isTrackIntent,
    choiceData,
  }
}];

// ── Handle choice selection (category/type/subtype) ──────────────────────
const data = $input.first().json;
const choice = data.choiceData;
const odooBase = $env.ODOO_BASE_URL || '';

if (!choice) {
  return [{ json: { ...data, routeAction: 'ai_general' } }];
}

return [{ json: {
  ...data,
  routeAction: 'choice_' + choice.type,
  choiceType: choice.type,
  choiceId: choice.id,
  choiceName: choice.name,
  odooBase,
} }];

// ── Build final structured response ────────────────────────────────────────
const parsed = $('Parse Input & Detect Intent').first().json;
const msg = parsed.message.toLowerCase();

// ── Determine what came through ────────────────────────────────────────────
let aiReply = '';
let choiceList = [];
let choiceType = '';
let action = '';
let applyUrl = '';
let newConvState = { ...parsed.conversationState };

// Try to get AI reply from OpenAI node
try {
  const openaiData = $('SAHAB AI — GPT-4o').first();
  if (openaiData && openaiData.json && openaiData.json.message) {
    aiReply = openaiData.json.message.content || '';
  }
} catch (e) {}

// Try to get categories list (if apply intent)
try {
  const catsData = $('Odoo: Get Categories').first();
  if (catsData && catsData.json && catsData.json.categories) {
    const cats = catsData.json.categories;
    if (cats.length > 0 && (parsed.isApplyIntent || !aiReply)) {
      choiceList = cats;
      choiceType = 'category';
      newConvState.step = 'select_category';
      if (!aiReply) {
        aiReply = 'يسعدنا مساعدتكم في تأمينكم! 🤝\n\nتفضّلوا باختيار **فئة التأمين** المناسبة لكم:';
      }
    }
  }
} catch (e) {}

// Try to get types (if category chosen)
try {
  const typesData = $('Odoo: Get Types by Category').first();
  if (typesData && typesData.json && typesData.json.types && parsed.choiceData && parsed.choiceData.type === 'category') {
    choiceList = typesData.json.types;
    choiceType = 'type';
    newConvState.step = 'select_type';
    newConvState.selectedCategory = parsed.choiceData.id;
    aiReply = `ممتاز! اخترتم **${parsed.choiceData.name}**. 🎯\n\nتفضّلوا بإخباري أي نوع تأمين يناسبكم:`;
  }
} catch (e) {}

// Try to get subtypes (if type chosen)
try {
  const subtypesData = $('Odoo: Get Subtypes by Type').first();
  if (subtypesData && subtypesData.json && subtypesData.json.subtypes && parsed.choiceData && parsed.choiceData.type === 'type') {
    choiceList = subtypesData.json.subtypes;
    choiceType = 'subtype';
    newConvState.step = 'select_subtype';
    newConvState.selectedType = parsed.choiceData.id;
    aiReply = `رائع! اخترتم **${parsed.choiceData.name}**. 🛡️\n\nتفضّلوا بتحديد نوع التغطية المناسبة:`;
  }
} catch (e) {}

// Handle subtype selection → redirect to apply form
try {
  if (parsed.choiceData && parsed.choiceData.type === 'subtype') {
    action = 'redirect_apply';
    applyUrl = `/insurance/apply/${parsed.choiceData.id}`;
    newConvState.step = 'applying';
    aiReply = `ممتاز! اخترتم **${parsed.choiceData.name}**. 🌟\n\nجاري تحويلكم إلى استمارة الطلب.\nيسعدنا خدمتكم ويسّر الله أمركم. 🤝`;
  }
} catch (e) {}

// Handle lead creation response
try {
  const leadData = $('Odoo: Create CRM Lead').first();
  if (leadData && leadData.json && leadData.json.success) {
    // Lead was created - acknowledge it
    if (!aiReply) {
      aiReply = 'تم تسجيل استفساركم لدينا. 📋\n\nسيتواصل معكم أحد مستشارينا المتخصصين قريباً إن شاء الله.\n\nهل تودّون تقديم طلب تأمين الآن؟';
    }
  }
} catch (e) {}

// Handle new application creation response
try {
  const appData = $('Odoo: Create Insurance Application').first();
  if (appData && appData.json && appData.json.success) {
    const ref = appData.json.reference || '';
    const portalUrl = appData.json.portal_url || '/my/insurance';
    aiReply = `تهانينا! ✅ تم إنشاء طلب التأمين بنجاح!\n\n**رقم الطلب:** ${ref}\n\nيمكنكم متابعة حالة طلبكم عبر بوابة العملاء.\nفريقنا سيتواصل معكم خلال ساعتين. 🤝`;
    action = 'application_created';
    applyUrl = portalUrl;
  }
} catch (e) {}

// Fallback reply
if (!aiReply) {
  aiReply = 'السلام عليكم! أنا **SAHAB AI**، يسعدني خدمتكم في جميع احتياجاتكم التأمينية. 🌟\n\nكيف أقدر أساعدكم اليوم؟';
}

// ── Contextual quick replies ────────────────────────────────────────────────
const allQR = {
  motor:    ['أبي تأمين شامل', 'تأمين المسؤولية (TPL)', 'تأمين أسطول', 'عرض الأسعار'],
  medical:  ['تأمين طبي فردي', 'تأمين طبي جماعي', 'تأمين الأسنان', 'استشارة مجانية'],
  life:     ['تأمين حياة', 'تأمين حوادث شخصية', 'تأمين الأطفال', 'استشارة'],
  property: ['تأمين منزل', 'تأمين تجاري', 'تأمين حريق', 'عرض أسعار'],
  marine:   ['تأمين شحن بضائع', 'تأمين يخت', 'تأمين هيكل سفينة', 'استشارة'],
  claim:    ['تقديم مطالبة', 'الخط الساخن +968 2400 0000', 'تتبع مطالبتي', 'المستندات المطلوبة'],
  default:  ['أبي تأمين', 'تأمين السيارات', 'التأمين الطبي', 'تتبع طلبي'],
};

let quickReplies = allQR.default;
if (!choiceList.length) {
  if (msg.includes('motor') || msg.includes('سيارة') || msg.includes('مركبة') || msg.includes('car')) quickReplies = allQR.motor;
  else if (msg.includes('medical') || msg.includes('طبي') || msg.includes('صحة') || msg.includes('health')) quickReplies = allQR.medical;
  else if (msg.includes('life') || msg.includes('حياة') || msg.includes('حوادث')) quickReplies = allQR.life;
  else if (msg.includes('property') || msg.includes('منزل') || msg.includes('عقار') || msg.includes('home')) quickReplies = allQR.property;
  else if (msg.includes('marine') || msg.includes('بحري') || msg.includes('شحن')) quickReplies = allQR.marine;
  else if (msg.includes('claim') || msg.includes('مطالبة') || msg.includes('تعويض')) quickReplies = allQR.claim;
}

return [{ json: {
  reply: aiReply,
  quick_replies: choiceList.length ? [] : quickReplies,
  choice_list: choiceList,
  choice_type: choiceType,
  action: action,
  apply_url: applyUrl,
  conversation_state: newConvState,
  source: 'ai',
  session_id: parsed.sessionId,
  timestamp: new Date().toISOString(),
} }];
